n \n0000000009 00000 n \n0000000087 00000 n \n0000001334 00000 n \n0000001412 00000 n \n0000002526 00000 n \n0000002604 00000 n \n0000003392 00000 n \n0000003493 00000 n \n0000003705 00000 n \n0000003893 00000 n \ntrailer\n<<\n/Size 13\n/Root 12 0 R\n/Info 11 0 R\n>>\nstartxref\n3997\n%%EOF\n','2026-04-04 13:48:39','everyone','2026-04-04 08:18:38','[{\"question\": \"Which of the following is not a part of the human eye?\", \"options\": [\"Cornea\", \"Pupil\", \"Lens\", \"Liver\"], \"correct_answer\": \"D\", \"explanation\": \"The liver is an organ of the digestive system and not part of the human eye.\", \"type\": \"mcq\"}, {\"question\": \"The angle of incidence is equal to the angle of reflection. Which of the following correctly describes the law of reflection?\", \"options\": [\"The incident ray, the reflected ray, and the normal all lie in the same plane.\", \"The incident ray and the reflected ray are always parallel.\", \"The incident ray and the reflected ray are always perpendicular.\", \"The angle of incidence is always 90 degrees.\"], \"correct_answer\": \"A\", \"explanation\": \"This correctly describes the law of reflection.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following statements is true regarding the human eye\'s focusing ability?\", \"options\": [\"The eye can focus on objects at any distance.\", \"The eye can only focus on objects at a fixed distance.\", \"The eye can only focus on objects at close distances.\", \"The eye can only focus on objects at a fixed distance but can adjust the focus of the lens.\"], \"correct_answer\": \"D\", \"explanation\": \"The human eye\'s focusing ability allows it to adjust to focus on objects at different distances, including close and distant ones.\", \"type\": \"mcq\"}, {\"question\": \"In the human eye, the action of the lens changing shape to focus on close objects is called:\", \"options\": [\"Myopia\", \"Hyperopia\", \"Convergence\", \"Convergence of the eye\"], \"correct_answer\": \"C\", \"explanation\": \"Convergence refers to the action of the eye muscles working together to focus on objects that are close.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a property of a convex lens?\", \"options\": [\"It converges light rays.\", \"It diverges light rays.\", \"It neither converges nor diverges light rays.\", \"It only reflects light.\"], \"correct_answer\": \"A\", \"explanation\": \"A convex lens converges light rays, making it useful for focusing light and magnifying images.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is an example of an arithmetic progression?\", \"options\": [\"1, 2, 3, 4, 5\", \"2, 4, 6, 8, 10\", \"1, 3, 5, 7, 9\", \"2, 4, 8, 16, 32\"], \"correct_answer\": \"B\", \"explanation\": \"An arithmetic progression has a constant difference between each successive term, and in 2, 4, 6, 8, 10, the difference between each term is 2.\", \"type\": \"mcq\"}, {\"question\": \"The formula for the sum of the first n terms of an arithmetic progression is:\", \"options\": [\"S_n = n/2(2a + (n - 1)d)\", \"S_n = n/2(a + (n - 1)d)\", \"S_n = n/2(a + (n - 1)d^2)\", \"S_n = n/2(2a + nd)\"], \"correct_answer\": \"B\", \"explanation\": \"The sum of the first n terms of an arithmetic progression is given by S_n = n/2(a + (n - 1)d), where a is the first term and d is the common difference.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct representation of the Pythagorean theorem in a right-angled triangle?\", \"options\": [\"a^2 + b^2 = c\", \"a^2 - b^2 = c^2\", \"a^2 + b^2 = c^2\", \"a^2 - b^2 = c\"], \"correct_answer\": \"C\", \"explanation\": \"The Pythagorean theorem states that in a right-angled triangle, the square of the length of the hypotenuse (the side opposite the right angle) is equal to the sum of the squares of the lengths of the other two sides.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following statements is true regarding the periodic table classification of elements?\", \"options\": [\"Elements are classified based on their atomic mass.\", \"Elements are classified based on their electron configuration.\", \"Elements are classified based on their atomic number.\", \"Elements are classified based on their melting point.\"], \"correct_answer\": \"C\", \"explanation\": \"Elements are classified based on their atomic number, which determines their position in the periodic table.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct formula for the area of a circle?\", \"options\": [\"A = \\\\(\\\\pi r^2\\\\)\", \"A = \\\\(\\\\pi r\\\\)\", \"A = \\\\(\\\\pi r + 2\\\\pi r^2\\\\)\", \"A = \\\\(\\\\pi r^2 + 2\\\\pi r\\\\)\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a circle is A = \\\\(\\\\pi r^2\\\\), where \\\\(r\\\\) is the radius of the circle.\", \"type\": \"mcq\"}, {\"question\": \"What is the correct formula for the area of a trapezium?\", \"options\": [\"A = \\\\(\\frac{1}{2}h(a+b)\\\\)\", \"A = \\\\(\\frac{1}{2}h(a-b)\\\\)\", \"A = \\\\(\\frac{1}{2}h(a+b^2)\\\\)\", \"A = \\\\(\\frac{1}{2}h(a^2+b)\\\\)\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a trapezium is A = \\\\(\\frac{1}{2}h(a+b)\\\\), where \\\\(a\\\\) and \\\\(b\\\\) are the lengths of the parallel sides and \\\\(h\\\\) is the height of the trapezium.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct formula for the perimeter of a rectangle?\", \"options\": [\"P = 2(l + w)\", \"P = 2(l - w)\", \"P = 2(l + w^2)\", \"P = 2(l^2 + w)\"], \"correct_answer\": \"A\", \"explanation\": \"The perimeter of a rectangle is given by P = 2(l + w), where \\\\(l\\\\) is the length and \\\\(w\\\\) is the width of the rectangle.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct formula for the perimeter of a square?\", \"options\": [\"P = 4a\", \"P = 4a^2\", \"P = 4a + a^2\", \"P = 4a^2 + 4a\"], \"correct_answer\": \"A\", \"explanation\": \"The perimeter of a square is given by P = 4a, where \\\\(a\\\\) is the length of one side of the square.\", \"type\": \"mcq\"}, {\"question\": \"The formula for the area of a triangle is:\", \"options\": [\"A = \\\\(\\frac{1}{2}bh\\\\)\", \"A = \\\\(\\frac{1}{2}bh^2\\\\)\", \"A = \\\\(\\frac{1}{2}b^2h\\\\)\", \"A = \\\\(\\frac{1}{2}bh + h\\\\)\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a triangle is A = \\\\(\\frac{1}{2}bh\\\\), where \\\\(b\\\\) is the base and \\\\(h\\\\) is the height of the triangle.\", \"type\": \"mcq\"}, {\"question\": \"The formula for the area of a trapezium is:\", \"options\": [\"A = \\\\(\\frac{1}{2}h(b + a)\\\\)\", \"A = \\\\(\\frac{1}{2}h(b - a)\\\\)\", \"A = \\\\(\\frac{1}{2}h(b + a^2)\\\\)\", \"A = \\\\(\\frac{1}{2}h(b^2 + a)\\\\)\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a trapezium is A = \\\\(\\frac{1}{2}h(b + a)\\\\), where \\\\(b\\\\) and \\\\(a\\\\) are the lengths of the parallel sides and \\\\(h\\\\) is the height of the trapezium.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct formula for the area of a parallelogram?\", \"options\": [\"A = bh\", \"A = bh^2\", \"A = bh + h^2\", \"A = bh^2 + h\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a parallelogram is A = bh, where \\\\(b\\\\) is the base and \\\\(h\\\\) is the height.\", \"type\": \"mcq\"}, {\"question\": \"The formula for the area of a circle is:\", \"options\": [\"A = \\\\(\\\\pi r^2\\\\)\", \"A = \\\\(\\\\pi r\\\\)\", \"A = \\\\(\\\\pi r + 2\\\\pi r^2\\\\)\", \"A = \\\\(\\\\pi r^2 + 2\\\\pi r\\\\)\"], \"correct_answer\": \"A\", \"explanation\": \"The formula for the area of a circle is A = \\\\(\\\\pi r^2\\\\), where \\\\(r\\\\) is the radius of the circle.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct formula for the area of a circle?\", \"options\": [\"A = \\\\(\\\\pi r^2\\\\)\", \"A = \\\\(\\\\pi r\\\\)\", \"A =