n0000003165 00000 n \n0000000009 00000 n \n0000000087 00000 n \n0000001183 00000 n \n0000001261 00000 n \n0000002330 00000 n \n0000002408 00000 n \n0000002967 00000 n \n0000003068 00000 n \n0000003280 00000 n \n0000003468 00000 n \ntrailer\n<<\n/Size 13\n/Root 12 0 R\n/Info 11 0 R\n>>\nstartxref\n3572\n%%EOF\n','2026-04-10 13:27:44','everyone','2026-04-10 07:57:43','[{\"question\": \"What is the additive inverse of -15?\", \"options\": [\"15\", \"-15\", \"0\", \"15/1\"], \"correct_answer\": \"A\", \"explanation\": \"The additive inverse of a number is the number that, when added to the original number, results in zero.\", \"type\": \"mcq\"}, {\"question\": \"If a temperature is 20\\u00b0C and it decreases by 5\\u00b0C, what is the new temperature?\", \"options\": [\"15\\u00b0C\", \"25\\u00b0C\", \"10\\u00b0C\", \"-5\\u00b0C\"], \"correct_answer\": \"A\", \"explanation\": \"Temperature decreases by adding a negative value. So, 20\\u00b0C - 5\\u00b0C = 15\\u00b0C.\", \"type\": \"mcq\"}, {\"question\": \"What is the product of (-4) and (-6)?\", \"options\": [\"24\", \"-24\", \"4\", \"-6\"], \"correct_answer\": \"A\", \"explanation\": \"When multiplying two negative numbers, the result is positive.\", \"type\": \"mcq\"}, {\"question\": \"What is the perimeter of a square with a side length of 7 cm?\", \"options\": [\"24 cm\", \"28 cm\", \"14 cm\", \"49 cm\"], \"correct_answer\": \"B\", \"explanation\": \"The formula for the perimeter of a square is 4 times the length of one side.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a proper fraction?\", \"options\": [\"1/2\", \"3/4\", \"5/3\", \"4/5\"], \"correct_answer\": \"A\", \"explanation\": \"A proper fraction is a fraction where the numerator is less than the denominator.\", \"type\": \"mcq\"}, {\"question\": \"If a tree loses 1/5 of its leaves in autumn, what fraction of leaves remain?\", \"options\": [\"2/5\", \"3/5\", \"4/5\", \"5/5\"], \"correct_answer\": \"C\", \"explanation\": \"If 1/5 of the leaves are lost, 4/5 remain.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a correct representation of the phrase \'The temperature is 10\\u00b0C warmer than 20\\u00b0C\'?\", \"options\": [\"10 + 20\\u00b0C\", \"10 - 20\\u00b0C\", \"20 + 10\\u00b0C\", \"20 - 10\\u00b0C\"], \"correct_answer\": \"C\", \"explanation\": \"The phrase indicates addition of 10\\u00b0C to the initial temperature of 20\\u00b0C.\", \"type\": \"mcq\"}, {\"question\": \"What is the sum of the integers from -3 to 3?\", \"options\": [\"0\", \"-1\", \"1\", \"3\"], \"correct_answer\": \"A\", \"explanation\": \"Adding positive and negative integers in pairs (3+(-3)=0) until all numbers are considered results in 0.\", \"type\": \"mcq\"}, {\"question\": \"How many leaves did a tree lose if it had 100 leaves and 1/4 of them fell to the ground?\", \"options\": [\"25\", \"50\", \"75\", \"100\"], \"correct_answer\": \"A\", \"explanation\": \"To find 1/4 of 100, calculate \\\\( \\frac{100}{4} \\\\).\", \"type\": \"mcq\"}, {\"question\": \"What is the area of a rectangle with length 8 cm and width 5 cm?\", \"options\": [\"30 cm\\u00b2\", \"40 cm\\u00b2\", \"13 cm\\u00b2\", \"45 cm\\u00b2\"], \"correct_answer\": \"B\", \"explanation\": \"Area of a rectangle is calculated by multiplying length and width.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following statements is true about heat transfer by conduction?\", \"options\": [\"Heat is transferred from a hot body to a cold body\", \"Heat is transferred from a cold body to a hot body\", \"Heat transfer occurs when a medium is present\", \"Heat transfer is not affected by temperature differences\"], \"correct_answer\": \"C\", \"explanation\": \"Conduction requires a medium and occurs when there is a temperature difference.\", \"type\": \"mcq\"}, {\"question\": \"What is the result of \\\\( -3 \\times -2 \\\\)?\", \"options\": [\"-6\", \"6\", \"-1\", \"1\"], \"correct_answer\": \"B\", \"explanation\": \"Multiplying two negative numbers gives a positive result.\", \"type\": \"mcq\"}, {\"question\": \"If the price of a book is reduced by 1/3, what fraction of the original price is the new price?\", \"options\": [\"2/3\", \"1/3\", \"1/6\", \"2/9\"], \"correct_answer\": \"A\", \"explanation\": \"Reducing by 1/3 means keeping 2/3 of the original price.\", \"type\": \"mcq\"}, {\"question\": \"What is the product of 4 and -5?\", \"options\": [\"20\", \"-20\", \"10\", \"-10\"], \"correct_answer\": \"B\", \"explanation\": \"Multiplying a positive and a negative number gives a negative result.\", \"type\": \"mcq\"}, {\"question\": \"How many leaves will a tree have if it has 50 and then gains 15 more?\", \"options\": [\"50\", \"65\", \"100\", \"15\"], \"correct_answer\": \"B\", \"explanation\": \"To find total leaves, add the number of leaves it had to the number it gained.\", \"type\": \"mcq\"}, {\"question\": \"What is the perimeter of a rectangle with length 12 cm and width 4 cm?\", \"options\": [\"20 cm\", \"24 cm\", \"16 cm\", \"48 cm\"], \"correct_answer\": \"B\", \"explanation\": \"Perimeter of a rectangle is calculated by adding all sides.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following represents the phrase \'The temperature is 10\\u00b0C lower than 20\\u00b0C\'?\", \"options\": [\"10 + 20\\u00b0C\", \"10 - 20\\u00b0C\", \"20 + 10\\u00b0C\", \"20 - 10\\u00b0C\"], \"correct_answer\": \"B\", \"explanation\": \"The phrase indicates subtraction of 10\\u00b0C from the initial temperature of 20\\u00b0C.\", \"type\": \"mcq\"}, {\"question\": \"What is the result of \\\\( -4 \\times 3 \\\\)?\", \"options\": [\"-12\", \"12\", \"-4\", \"4\"], \"correct_answer\": \"A\", \"explanation\": \"Multiplying a negative and a positive number gives a negative result.\", \"type\": \"mcq\"}, {\"question\": \"If a tree loses 1/6 of its leaves, what fraction of leaves remain?\", \"options\": [\"5/6\", \"1/6\", \"1/5\", \"6/5\"], \"correct_answer\": \"A\", \"explanation\": \"If 1/6 of the leaves are lost, 5/6 remain.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is an example of convection?\", \"options\": [\"Heat transfer through a liquid\", \"Heat transfer through a solid\", \"Heat transfer through a gas\", \"Heat transfer through a vacuum\"], \"correct_answer\": \"C\", \"explanation\": \"Convection is heat transfer through a gas.\", \"type\": \"mcq\"}]'),(10,'2026-04-11','10','1.science - acids, bases and salts, electricity','',_binary '%PDF-1.3\n3 0 obj\n<</Type /Page\n/Parent 1 0 R\n/Resources 2 0 R\n/Contents 4 0 R>>\nendobj\n4 0 obj\n<</Filter /FlateDecode /Length 784>>\nstream\nxœ••mO\Û0\Ç\ß\ïS\ÜË¡Qc;qx3¦\ÓZ	!MH&q[C–TIJ\×}úóP9¤+İ«ª\Öÿ\î\ì\ßÿ\î\Â\á\ëJ„›38»bÀ\\B)\Ì\æp93Gœ3\â‡\à‡‚0f	|ü=L¯\Ç\ÓSG—7\×\ÓÙ‡˜=·ò³+Œ÷2\ÔG¬w\ä0\Â0§\ç’ ¬sNd¥ÎSî¨;b\Ì\Ê\Øj]N8«µ\ãT–\å90:±§Mc­²XÁd¬“òd©JY¥L+<P©Š«BÇº\Úö\î\Ï\ŞŞ¿\É\í‚p^\çfî—²]BµT°Š Ÿƒ„2O×•\Î3\Ø\èj‰ÿ—Û¤\È*s\çx›¬*d­@=ƒ\ßø„Ç‘7Ÿ\ßò\Û\Ëóq›ú\0ğ\å\ç	øƒ÷{.#\"\è4¨ñ†\Z\ã§\ÛiÆ¨	†\Z\Ê:cP3AMx\"\ácXƒŸD:^š—\ZFó<Mó\Îš„U‘¯TQmpÆš£7 Ôµ\\\å\Å/\ãj\í²w$x`~,4·jv¤ú\Ú%FÑ€8Â†\Õ4w>T\Î\r\"˜M°4\İ\×vÈ \è[²œxZ¾±òŠ€¸\r\ç0bl¸\çõÇª.22Œa%u:«å…’qİ‹\Ñø\ÎyÁ\'ˆø\ìl ı² ~3ıG=ª\ï¢\Ç\ÑQ¦¹x\Zú¶imE3‹&\Ë\0r\ÂÛ«¦¨	ÀKõ>\î†\ĞvÉªP‡C\ï8¶ş˜\×\ï¹\Ñ?›\İ\áœ8Í¬¹ı} \æs\Ü,ukg\í–\É\Ó-\Z‘7\äÑ™d\ì_u7\0]Å“‡\ØZ¡\Ís¢btÓ¬7;õ\à\Í\Ü¬\É7X¯³\ã±\éBjó½\Íw¯\ÌŞ‰uBB=ôD­T–”j»R†‚\êüœ†õ)\æ\ï\ÂR\Ø\êª\Ğe…#\Û_=%–D¡\í\Ò™Á\ÌWöš[/–‡‘0O\Çëµ·‰YEC¥+ˆ\à6ø{%_\Ş\É\Îñ|ø·|\Óÿü\àK‰Š\Ş\è\ãw\ßk™g8\ã\çL\ÂB¦¯2C˜±JSCy“/ü6ûHTúI5’\èB\Å\İw°EŸ\í_<8\Ùa³	\æ˜\ê%lºSt\nendstream\nendobj\n5 0 obj\n<</Type /Page\n/Parent 1 0 R\n/Resources 2 0 R\n/Contents 6 0 R>>\nendobj\n6 0 obj\n<</Filter /FlateDecode /Length 540>>\nstream\nxœ­”Qo\Ó0\Ç\ß÷)\î‘I\Ã\Äv\ì\ÔO¨-›V$&´FB“x‰R·13v”J¿=\ÛTm!{¨\ÔXşÿ\ï\îw\ç#ğñ*A,ƒ\í\Õ,‡ww0FIù\Znóıœ¾8\"£L@&\Â\ä+xóùşi¹˜/o`~ûi±\ÌŸ®!ÿvt81¥aoÀ9¢I0\0€\é\×k¸k\ìwp•#7…S?%8¾kÛªğ-µ,]cW2\nppK9Jy\ï6‹İ\êƒ\Û\Ñı/n„#Nz·¹w{°ıukm·§’„£l\ÒK>x\ÉT;\Ù\Êl.j_r†Ï¼v‚/•*+°\ëÿ\ÚjoÒ¹ª\n(«¢)JJµN•\İ%f