00001903 00000 n \n0000000009 00000 n \n0000000087 00000 n \n0000001124 00000 n \n0000001202 00000 n \n0000001706 00000 n \n0000001807 00000 n \n0000002017 00000 n \n0000002169 00000 n \ntrailer\n<<\n/Size 11\n/Root 10 0 R\n/Info 9 0 R\n>>\nstartxref\n2273\n%%EOF\n','2026-04-11 03:12:21','student,parent','2026-04-10 21:42:21','[{\"question\": \"What is the pH of a solution with a hydrogen ion concentration of 1 x 10^-7 M?\", \"options\": [\"7\", \"6\", \"8\", \"9\"], \"correct_answer\": \"A\", \"explanation\": \"The pH is calculated as -log[H+]. For [H+] = 1 x 10^-7 M, pH = 7.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a property of a base?\", \"options\": [\"Forms an acidic solution\", \"Neutralizes an acid\", \"Forms a basic solution\", \"Forms a salt with an acid\"], \"correct_answer\": \"C\", \"explanation\": \"Bases form a basic solution. They can neutralize acids and react with acids to form salts.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a conjugate acid-base pair in the reaction HCO3^- + H2O \\u21cc H2CO3 + OH^-?\", \"options\": [\"HCO3^- and OH^-\", \"H2CO3 and H2O\", \"HCO3^- and H2CO3\", \"H2O and OH^-\"], \"correct_answer\": \"C\", \"explanation\": \"HCO3^- is the conjugate base of H2CO3 and OH^- is the conjugate base of H2O.\", \"type\": \"mcq\"}, {\"question\": \"What is the effect of an electrolyte on the conductivity of a solution?\", \"options\": [\"Decreases conductivity\", \"Increases conductivity\", \"No effect on conductivity\", \"Depends on the type of electrolyte\"], \"correct_answer\": \"B\", \"explanation\": \"Electrolytes increase the conductivity of a solution by dissociating into ions, allowing them to carry the electric current.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a characteristic property of a strong electrolyte solution?\", \"options\": [\"High conductivity\", \"High pH\", \"Weak conductivity\", \"Low concentration\"], \"correct_answer\": \"A\", \"explanation\": \"Strong electrolytes completely dissociate in solution, resulting in high conductivity.\", \"type\": \"mcq\"}, {\"question\": \"When a galvanic cell is working, which of the following describes the direction of electron flow?\", \"options\": [\"From the negative to the positive electrode\", \"From the positive to the negative electrode\", \"No electron flow\", \"Alternating electron flow\"], \"correct_answer\": \"A\", \"explanation\": \"In a galvanic cell, electrons flow from the negative to the positive electrode.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a characteristic of a conductor in electricity?\", \"options\": [\"Repels all charges\", \"Repels like charges\", \"Attracts like charges\", \"Allows charges to flow freely\"], \"correct_answer\": \"D\", \"explanation\": \"A conductor allows charges to flow freely, which is why it conducts electricity.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a characteristic property of a conductor in electricity?\", \"options\": [\"Repels all charges\", \"Repels like charges\", \"Attracts like charges\", \"Allows charges to flow freely\"], \"correct_answer\": \"D\", \"explanation\": \"A conductor allows charges to flow freely, which is why it conducts electricity.\", \"type\": \"mcq\"}, {\"question\": \"In an electrolytic cell, the oxidation reaction takes place at which electrode?\", \"options\": [\"Cathode\", \"Anode\", \"Both cathode and anode\", \"Neither cathode nor anode\"], \"correct_answer\": \"B\", \"explanation\": \"Oxidation reactions occur at the anode in an electrolytic cell.\", \"type\": \"mcq\"}, {\"question\": \"Which of the following is a characteristic of a non-conductor in electricity?\", \"options\": [\"Repels all charges\", \"Repels like charges\", \"Attracts like charges\", \"Allows charges to flow freely\"], \"correct_answer\": \"A\", \"explanation\": \"A non-conductor repels all charges, preventing the flow of electric current.\", \"type\": \"mcq\"}]');
